#include <type_traits>
// 业务入口不把死者当作新的签约人；激活只消费候选生前已经给出的可撤回条件许可。
#include "family_legacy_commands.hpp"
#include "biological_control_sources.hpp"
#include "succession_personal_assets.hpp"
namespace hanmo::resident {
// 外部BoundaryValue即使绕过文本parser，也先逐层拒重复键。
Outcome<FamilyLegacyCommand> decode_family_legacy_command(const StableId& kind,const BoundaryValue& args){try{auto unique=validate_succession_json_unique(args);if(!unique.ok)return {false,{},unique.error};using namespace boundary;FamilyLegacyCommand out;out.kind=kind;
    if(kind=="family_legacy_accept"){fields(args,{"request_id"},{},kind);out.request_id=get_string(args,"request_id",kind);}
    else if(kind=="family_legacy_revoke"){fields(args,{"request_id","consent_fact_id"},{},kind);out.request_id=get_string(args,"request_id",kind);out.consent_fact_id=get_string(args,"consent_fact_id",kind);}
    else if(kind=="family_legacy_activate"){fields(args,{"consent_fact_id"},{},kind);out.consent_fact_id=get_string(args,"consent_fact_id",kind);}
    else fail("UnknownFamilyLegacyCommand",kind);
    if((kind!="family_legacy_activate"&&(out.request_id.empty()||out.request_id.size()>256))||(kind!="family_legacy_accept"&&(out.consent_fact_id.empty()||out.consent_fact_id.size()>256)))fail("InvalidFamilyLegacyCommand",kind);return {true,std::move(out),{}};
}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
// activation的actor是原控制上下文，不表示死亡人物能够再作决定或处分资产。
Outcome<FamilyLegacyQuote> preview_family_legacy_command(const CommonStore& c,const FamilyState& family,const FamilyDeathState& deaths,const FamilyDeathOriginRead& read,const InteractionState& state,const InteractionCatalog& interaction,const InteractionAccess& access,const LegacyControlConsentCatalog& catalog,const FamilyLegacyState& legacy,const FamilyLegacyPlayableRead& playable,const StableId& actor,const FamilyLegacyCommand& command,const DiscipleControlRelationContext* disciple,const BiologicalControlDecisionContext* biological,const CollateralControlDecisionContext* collateral,const FamilyContinuationPeopleRead4* complete_people){
    if((!catalog.enabled&&!(biological&&biological->catalog.enabled))||!interaction.common)return {false,{},common_failure("LegacyControlConsentProfileRequired").error};if(actor!=c.state().metadata.player_actor_id)return {false,{},common_failure("PlayerCommandAuthorityRequired").error};FamilyLegacyQuote result;
    if(command.kind=="family_legacy_activate"){if(!command.request_id.empty()||command.consent_fact_id.empty())return {false,{},common_failure("InvalidFamilyLegacyCommand").error};auto quote=preview_family_legacy_activation(c,family,deaths,read,*interaction.common,interaction,catalog,legacy,playable,command.consent_fact_id,disciple,biological,collateral,complete_people);if(!quote.ok)return {false,{},quote.error};result.activation=std::move(quote.value);return {true,std::move(result),{}};}
    if(command.kind!="family_legacy_accept"&&command.kind!="family_legacy_revoke")return {false,{},common_failure("UnknownFamilyLegacyCommand").error};auto valid=validate_family_legacy(c,family,deaths,read,*interaction.common,interaction,catalog,legacy,playable,disciple,biological,collateral,complete_people);if(!valid.ok)return {false,{},valid.error};const auto* d=catalog.definitions.find(command.request_id);if(!d||d->predecessor_actor_id!=actor)return {false,{},common_failure("LegacyControlConsentRequestMismatch").error};
    if(command.kind=="family_legacy_accept"&&!command.consent_fact_id.empty())return {false,{},common_failure("UnexpectedLegacyConsentTarget").error};
    if(command.kind=="family_legacy_revoke"){const auto* accepted=legacy.consents.find(command.consent_fact_id);if(!accepted||accepted->source.request_id!=command.request_id||accepted->source.predecessor_actor_id!=actor)return {false,{},common_failure("LegacyRevocationSourceMismatch").error};for(const auto& r:legacy.revocations.rows())if(r.second.consent_fact_id==command.consent_fact_id)return {false,{},common_failure("LegacyConsentAlreadyClosed").error};for(const auto& r:legacy.activations.rows())if(r.second.consent_fact_id==command.consent_fact_id)return {false,{},common_failure("LegacyConsentAlreadyClosed").error};}
    auto quote=preview_legacy_control_decision(c,family,state,interaction,access,catalog,actor,d->successor_actor_id,d->id,command.kind=="family_legacy_accept"?"accept":"revoke",disciple,command.kind=="family_legacy_revoke"?legacy.consents.find(command.consent_fact_id)->source.relation_fact_id:StableId{},biological,collateral,complete_people);if(!quote.ok)return {false,{},quote.error};result.decision=std::move(quote.value);return {true,std::move(result),{}};
}
// 原报价类型与命令必须完全匹配，不接受零时命令借另一种报价切人。
Outcome<FamilyEffect> apply_family_legacy_command(CommonStore& c,const FamilyState& family,const FamilyDeathState& deaths,const FamilyDeathOriginRead& read,const InteractionState& state,const InteractionCatalog& interaction,const InteractionAccess& access,const LegacyControlConsentCatalog& catalog,FamilyLegacyState& legacy,const FamilyLegacyPlayableRead& playable,const StableId& actor,const FamilyLegacyCommand& command,const FamilyLegacyQuote& quote,const DiscipleControlRelationContext* disciple,const BiologicalControlDecisionContext* biological,const CollateralControlDecisionContext* collateral,const FamilyContinuationPeopleRead4* complete_people,OriginalContinuationConsentWrite* continuation_writer){
    auto fresh=preview_family_legacy_command(c,family,deaths,read,state,interaction,access,catalog,legacy,playable,actor,command,disciple,biological,collateral,complete_people);if(!fresh.ok)return {false,{},fresh.error};Outcome<StableId> written;StableId successor;
    if(command.kind=="family_legacy_activate"){if(!quote.activation||quote.decision||quote.activation->consent_fact_id!=command.consent_fact_id)return {false,{},common_failure("StaleLegacyControlActivation").error};successor=quote.activation->successor_actor_id;written=activate_family_legacy_control(c,family,deaths,read,*interaction.common,interaction,catalog,legacy,playable,*quote.activation,disciple,biological,collateral,complete_people);}
    else {if(!quote.decision||quote.activation||!fresh.value.decision||!legacy_control_decision_equal(quote.decision->decision,fresh.value.decision->decision))return {false,{},common_failure("StaleLegacyControlDecision").error};successor=quote.decision->decision.successor_actor_id;written=record_family_legacy_decision(c,family,deaths,read,state,interaction,access,catalog,legacy,*quote.decision,command.consent_fact_id,playable,disciple,biological,collateral,complete_people,continuation_writer);}
    if(!written.ok)return {false,{},written.error};FamilyEffect effect;effect.success=true;effect.fact_id=written.value;effect.heir_actor_id=successor;effect.player_actor_id=c.state().metadata.player_actor_id;return {true,std::move(effect),{}};
}
// 同一翻译单元必须只有头中声明的实际签名，防新尾参误成未定义旧入口的静默重载。
static_assert(std::is_pointer_v<decltype(&preview_family_legacy_command)>,"legacy typed access signature must be unambiguous");
static_assert(std::is_pointer_v<decltype(&apply_family_legacy_command)>,"legacy typed access signature must be unambiguous");

}
